import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { getSessionUser } from "@/lib/session";

export const dynamic = "force-dynamic";

// Simulated wallet association. Never touches key material — the client only
// reports a public address generated by the simulated wallet.
export async function POST(req: NextRequest) {
  try {
    const user = await getSessionUser();
    const body = await req.json().catch(() => ({}));
    const address = (body as { address?: string }).address;
    const provider = (body as { provider?: string }).provider ?? "Simulated Phantom";
    if (!address || address.length < 20) {
      return NextResponse.json({ error: "Invalid wallet address" }, { status: 400 });
    }
    const existing = await db.wallet.findUnique({ where: { address } });
    if (!existing) {
      await db.wallet.create({ data: { userId: user.id, address, provider, verified: true } });
      await db.notification.create({
        data: {
          userId: user.id,
          kind: "SECURITY",
          title: "Wallet connected",
          body: `${provider.slice(0, 24)} · ${address.slice(0, 4)}…${address.slice(-4)} is now associated with your account.`,
        },
      });
      await db.activityEvent.create({
        data: { kind: "MILESTONE", title: `${user.displayName} connected a wallet`, meta: JSON.stringify({ provider }) },
      });
    }
    return NextResponse.json({ ok: true, address, provider });
  } catch (err) {
    console.error("wallet connect error", err);
    return NextResponse.json({ error: "Wallet connection failed" }, { status: 500 });
  }
}
